INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (559, 1, '연결 수와 실행 중 수는 다르다', '지금 서버에는 접속만 해 두고 아무 쿼리도 하지 않는 **유휴 세션 세 개**가 있습니다. 서버 전체(GLOBAL) 상태에서 아래 두 값을 읽어 저장하세요.
- `/tmp/connected.txt` : 지금 **맺어져 있는 연결 수** (`Threads_connected`)
- `/tmp/running.txt` : 지금 **쿼리를 실행 중인 스레드 수** (`Threads_running`)

(값만. 지금 명령을 치는 내 접속도 둘 다에 1 씩 포함됩니다.)', '`SHOW GLOBAL STATUS LIKE ''Threads%'';` 로 이름을 확인하고, `-N` 과 `cut -f2` 로 값 열만 뽑아 저장하세요.', 'mariadb -e "SHOW GLOBAL STATUS LIKE ''Threads%''"
mariadb -N -e "SHOW GLOBAL STATUS LIKE ''Threads_connected''" | cut -f2 > /tmp/connected.txt
mariadb -N -e "SHOW GLOBAL STATUS LIKE ''Threads_running''" | cut -f2 > /tmp/running.txt
cat /tmp/connected.txt /tmp/running.txt

# Threads_connected 는 연결 총수(유휴 포함), Threads_running 은 그 순간 실제로 일하는 수. 연결이 많아도 running 이 작으면 한가한 것이다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; for id in $(mariadb -N -e \\"SELECT id FROM information_schema.processlist WHERE id<>CONNECTION_ID()\\"); do mariadb -e \\"KILL $id\\" >/dev/null 2>&1; done; mariadb -e ''SET GLOBAL slow_query_log=0; SET GLOBAL long_query_time=10''; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, amount INT NOT NULL) ENGINE=InnoDB; INSERT INTO orders (customer_id, amount) SELECT seq % 1000, seq % 500 FROM seq_1_to_30000; CREATE TABLE logs (id INT AUTO_INCREMENT PRIMARY KEY, msg VARCHAR(255) NOT NULL) ENGINE=InnoDB; INSERT INTO logs (msg) SELECT REPEAT(\\"x\\", 200) FROM seq_1_to_20000; CREATE TABLE tags (id INT PRIMARY KEY, name VARCHAR(20)) ENGINE=InnoDB;''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; for i in 1 2 3; do nohup sh -c ''(sleep 600) | mariadb shop'' >/dev/null 2>&1 & done; sleep 1"]', '["sh", "-c", "( [ -n \\"$(cat /tmp/connected.txt)\\" ] && [ -n \\"$(cat /tmp/running.txt)\\" ] ) && ( [ $(( $(cat /tmp/connected.txt) - $(cat /tmp/running.txt) )) -eq 3 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "두 파일에 숫자가 있다", "cmd": ["sh", "-c", "[ -n \\"$(cat /tmp/connected.txt)\\" ] && [ -n \\"$(cat /tmp/running.txt)\\" ]"]}, {"label": "연결 수가 실행 수보다 유휴 세션 3개만큼 많다", "cmd": ["sh", "-c", "[ $(( $(cat /tmp/connected.txt) - $(cat /tmp/running.txt) )) -eq 3 ]"]}]', '[{"title": "SHOW STATUS", "url": "https://mariadb.com/kb/en/show-status/"}, {"title": "서버 상태 변수", "url": "https://mariadb.com/kb/en/server-status-variables/"}]'),
  (559, 2, '연결 한도에 얼마나 가까운가', '`max_connections` 는 동시에 맺을 수 있는 연결의 **한도(설정값)** 이고, `Max_used_connections` 는 서버가 켜진 뒤 **실제로 가장 많이 맺었던 연결 수(상태값)** 입니다. 둘을 비교하면 한도에 얼마나 가까워졌는지 알 수 있습니다.

`/tmp/max.txt` 에 **한도 `max_connections`**, `/tmp/used.txt` 에 **역대 최대 연결 수 `Max_used_connections`** 를 저장하세요. (값만)', '하나는 `SELECT @@변수` 또는 `SHOW VARIABLES` 로, 다른 하나는 `SHOW GLOBAL STATUS` 로 읽습니다. 설정값과 상태값이 어디서 나오는지 구분하세요.', 'mariadb -N -e ''SELECT @@max_connections'' > /tmp/max.txt
mariadb -N -e "SHOW GLOBAL STATUS LIKE ''Max_used_connections''" | cut -f2 > /tmp/used.txt
cat /tmp/max.txt /tmp/used.txt

# used 가 max 에 가까워지면 Too many connections 직전이다. VARIABLES = 설정, STATUS = 서버가 센 값', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; for id in $(mariadb -N -e \\"SELECT id FROM information_schema.processlist WHERE id<>CONNECTION_ID()\\"); do mariadb -e \\"KILL $id\\" >/dev/null 2>&1; done; mariadb -e ''SET GLOBAL slow_query_log=0; SET GLOBAL long_query_time=10''; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, amount INT NOT NULL) ENGINE=InnoDB; INSERT INTO orders (customer_id, amount) SELECT seq % 1000, seq % 500 FROM seq_1_to_30000; CREATE TABLE logs (id INT AUTO_INCREMENT PRIMARY KEY, msg VARCHAR(255) NOT NULL) ENGINE=InnoDB; INSERT INTO logs (msg) SELECT REPEAT(\\"x\\", 200) FROM seq_1_to_20000; CREATE TABLE tags (id INT PRIMARY KEY, name VARCHAR(20)) ENGINE=InnoDB;''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; for i in 1 2 3; do nohup sh -c ''(sleep 600) | mariadb shop'' >/dev/null 2>&1 & done; sleep 1"]', '["sh", "-c", "( [ \\"$(cat /tmp/max.txt)\\" = \\"$(mariadb -N -e ''SELECT @@max_connections'')\\" ] ) && ( [ \\"$(cat /tmp/used.txt)\\" -ge 4 ] && [ \\"$(cat /tmp/used.txt)\\" -le \\"$(cat /tmp/max.txt)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "max 가 설정값과 같다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/max.txt)\\" = \\"$(mariadb -N -e ''SELECT @@max_connections'')\\" ]"]}, {"label": "used 가 숫자이고 한도 이하다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/used.txt)\\" -ge 4 ] && [ \\"$(cat /tmp/used.txt)\\" -le \\"$(cat /tmp/max.txt)\\" ]"]}]', '[{"title": "SHOW STATUS", "url": "https://mariadb.com/kb/en/show-status/"}, {"title": "서버 상태 변수", "url": "https://mariadb.com/kb/en/server-status-variables/"}]'),
  (559, 3, '접속 실패 횟수 읽기', '누군가 틀린 비밀번호로 접속을 시도하고 있다는 제보가 있습니다. 서버는 **맺지 못한 접속 시도**의 횟수를 `Aborted_connects` 로 세어 둡니다. 그 값을 `/tmp/ab.txt` 에 저장하세요. (값만, 전역 상태)', '`SHOW GLOBAL STATUS LIKE ''Aborted%'';` 에는 비슷한 이름이 두 개 있습니다. 접속 **자체를 못 맺은** 쪽을 고르세요.', 'mariadb -e "SHOW GLOBAL STATUS LIKE ''Aborted%''"
mariadb -N -e "SHOW GLOBAL STATUS LIKE ''Aborted_connects''" | cut -f2 > /tmp/ab.txt
cat /tmp/ab.txt

# Aborted_connects = 접속 실패(인증 실패 등). Aborted_clients = 맺은 뒤 비정상으로 끊김. 갑자기 늘면 무차별 대입이나 앱 설정 오류를 의심한다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; for id in $(mariadb -N -e \\"SELECT id FROM information_schema.processlist WHERE id<>CONNECTION_ID()\\"); do mariadb -e \\"KILL $id\\" >/dev/null 2>&1; done; mariadb -e ''SET GLOBAL slow_query_log=0; SET GLOBAL long_query_time=10''; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, amount INT NOT NULL) ENGINE=InnoDB; INSERT INTO orders (customer_id, amount) SELECT seq % 1000, seq % 500 FROM seq_1_to_30000; CREATE TABLE logs (id INT AUTO_INCREMENT PRIMARY KEY, msg VARCHAR(255) NOT NULL) ENGINE=InnoDB; INSERT INTO logs (msg) SELECT REPEAT(\\"x\\", 200) FROM seq_1_to_20000; CREATE TABLE tags (id INT PRIMARY KEY, name VARCHAR(20)) ENGINE=InnoDB;''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; for i in 1 2 3; do mariadb -uapp -pwrong -e ''select 1'' >/dev/null 2>&1; done; true"]', '["sh", "-c", "( [ \\"$(cat /tmp/ab.txt)\\" -ge 3 ] ) && ( [ \\"$(cat /tmp/ab.txt)\\" = \\"$(mariadb -N -e \\"SHOW GLOBAL STATUS LIKE ''Aborted_connects''\\" | cut -f2)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "값이 3 이상이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/ab.txt)\\" -ge 3 ]"]}, {"label": "실제 상태값과 같다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/ab.txt)\\" = \\"$(mariadb -N -e \\"SHOW GLOBAL STATUS LIKE ''Aborted_connects''\\" | cut -f2)\\" ]"]}]', '[{"title": "SHOW STATUS", "url": "https://mariadb.com/kb/en/show-status/"}, {"title": "서버 상태 변수", "url": "https://mariadb.com/kb/en/server-status-variables/"}]'),
  (559, 4, '누적 카운터는 차이로 읽는다', '`Com_select` 는 서버가 켜진 뒤 실행한 `SELECT` 의 **누적 개수**입니다. 누적값 자체보다 **일정 시간 동안 얼마나 늘었는지**(차이)가 의미 있습니다. 직접 재 봅니다.

1. 지금의 `Com_select` 를 읽어 둔다
2. `SELECT 1` 을 **정확히 10번** 실행한다 (`mariadb -e` 로 10번)
3. 다시 `Com_select` 를 읽는다

두 값의 **차이(나중 값 − 처음 값)** 를 `/tmp/delta.txt` 에 저장하세요. (숫자만. `SHOW STATUS` 자체는 `Com_select` 에 포함되지 않습니다.)', '값을 변수에 담으면 편합니다. `a=$(...)`, 반복은 `for i in $(seq 10); do ...; done`, 계산은 `$((b-a))` 입니다.', 'a=$(mariadb -N -e "SHOW GLOBAL STATUS LIKE ''Com_select''" | cut -f2)
for i in $(seq 10); do mariadb -e ''SELECT 1'' >/dev/null; done
b=$(mariadb -N -e "SHOW GLOBAL STATUS LIKE ''Com_select''" | cut -f2)
echo $((b-a)) > /tmp/delta.txt
cat /tmp/delta.txt

# 모니터링 도구도 이렇게 ''지금 값 − 이전 값'' 을 시간으로 나눠 초당 쿼리 수 같은 그래프를 만든다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; for id in $(mariadb -N -e \\"SELECT id FROM information_schema.processlist WHERE id<>CONNECTION_ID()\\"); do mariadb -e \\"KILL $id\\" >/dev/null 2>&1; done; mariadb -e ''SET GLOBAL slow_query_log=0; SET GLOBAL long_query_time=10''; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, amount INT NOT NULL) ENGINE=InnoDB; INSERT INTO orders (customer_id, amount) SELECT seq % 1000, seq % 500 FROM seq_1_to_30000; CREATE TABLE logs (id INT AUTO_INCREMENT PRIMARY KEY, msg VARCHAR(255) NOT NULL) ENGINE=InnoDB; INSERT INTO logs (msg) SELECT REPEAT(\\"x\\", 200) FROM seq_1_to_20000; CREATE TABLE tags (id INT PRIMARY KEY, name VARCHAR(20)) ENGINE=InnoDB;''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(cat /tmp/delta.txt)\\" = 10 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "차이가 10 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/delta.txt)\\" = 10 ]"]}]', '[{"title": "SHOW STATUS", "url": "https://mariadb.com/kb/en/show-status/"}, {"title": "서버 상태 변수", "url": "https://mariadb.com/kb/en/server-status-variables/"}]'),
  (559, 5, '느린 쿼리 개수 재기', '`Slow_queries` 는 `long_query_time` 을 넘긴 쿼리의 누적 개수입니다(느린 쿼리 로그 파일을 켜 두지 않아도 셉니다). 기준을 **0.5초**로 바꾼 뒤 아래를 하세요.

1. `SET GLOBAL long_query_time=0.5;` 로 기준을 맞춘다
2. 지금의 `Slow_queries` 를 읽어 둔다
3. `SELECT SLEEP(1)` 을 **2번** 실행한다 (각각 1초가 걸리니 기준을 넘습니다)
4. 다시 읽어 **증가량**을 `/tmp/slow.txt` 에 저장', '`SET GLOBAL` 은 **새로 맺는 접속**부터 적용됩니다. 앞 문제처럼 값을 변수에 담아 차이를 계산하세요.', 'mariadb -e ''SET GLOBAL long_query_time=0.5''
a=$(mariadb -N -e "SHOW GLOBAL STATUS LIKE ''Slow_queries''" | cut -f2)
mariadb -e ''SELECT SLEEP(1)'' >/dev/null
mariadb -e ''SELECT SLEEP(1)'' >/dev/null
b=$(mariadb -N -e "SHOW GLOBAL STATUS LIKE ''Slow_queries''" | cut -f2)
echo $((b-a)) > /tmp/slow.txt
cat /tmp/slow.txt

# 증가량이 2. 하루 중 이 값이 갑자기 늘면 느린 쿼리 로그를 켜고 원인을 찾는다(513 참고)', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; for id in $(mariadb -N -e \\"SELECT id FROM information_schema.processlist WHERE id<>CONNECTION_ID()\\"); do mariadb -e \\"KILL $id\\" >/dev/null 2>&1; done; mariadb -e ''SET GLOBAL slow_query_log=0; SET GLOBAL long_query_time=10''; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, amount INT NOT NULL) ENGINE=InnoDB; INSERT INTO orders (customer_id, amount) SELECT seq % 1000, seq % 500 FROM seq_1_to_30000; CREATE TABLE logs (id INT AUTO_INCREMENT PRIMARY KEY, msg VARCHAR(255) NOT NULL) ENGINE=InnoDB; INSERT INTO logs (msg) SELECT REPEAT(\\"x\\", 200) FROM seq_1_to_20000; CREATE TABLE tags (id INT PRIMARY KEY, name VARCHAR(20)) ENGINE=InnoDB;''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(cat /tmp/slow.txt)\\" = 2 ] ) && ( [ \\"$(mariadb -N -e ''SELECT @@global.long_query_time <= 0.5'')\\" = 1 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "증가량이 2 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/slow.txt)\\" = 2 ]"]}, {"label": "기준이 0.5초 이하다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N -e ''SELECT @@global.long_query_time <= 0.5'')\\" = 1 ]"]}]', '[{"title": "SHOW STATUS", "url": "https://mariadb.com/kb/en/show-status/"}, {"title": "서버 상태 변수", "url": "https://mariadb.com/kb/en/server-status-variables/"}]'),
  (559, 6, '버퍼 풀 적중률 재료 모으기', 'InnoDB 는 자주 쓰는 데이터를 메모리(**버퍼 풀**)에 올려 두고 읽습니다. 읽기 요청 중 **디스크까지 가야 했던 비율**이 낮을수록 좋습니다. 재료가 되는 두 상태값을 저장하세요.
- `/tmp/requests.txt` : 버퍼 풀에 **논리적으로 읽기를 요청한 횟수** (`Innodb_buffer_pool_read_requests`)
- `/tmp/reads.txt` : 그중 **메모리에 없어서 디스크에서 읽은 횟수** (`Innodb_buffer_pool_reads`)', '요청 수는 `read_requests`, 디스크에서 읽은 수는 `reads` 입니다. 이름이 비슷하니 헷갈리지 마세요.', 'mariadb -e "SHOW GLOBAL STATUS LIKE ''Innodb_buffer_pool_read%''"
mariadb -N -e "SHOW GLOBAL STATUS LIKE ''Innodb_buffer_pool_read_requests''" | cut -f2 > /tmp/requests.txt
mariadb -N -e "SHOW GLOBAL STATUS LIKE ''Innodb_buffer_pool_reads''" | cut -f2 > /tmp/reads.txt
echo "적중률 = $(( 100 - 100 * $(cat /tmp/reads.txt) / $(cat /tmp/requests.txt) ))%"

# 적중률 = 1 − reads / read_requests. 보통 99% 이상이면 건강. 낮으면 buffer pool 이 데이터보다 작은지 점검', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; for id in $(mariadb -N -e \\"SELECT id FROM information_schema.processlist WHERE id<>CONNECTION_ID()\\"); do mariadb -e \\"KILL $id\\" >/dev/null 2>&1; done; mariadb -e ''SET GLOBAL slow_query_log=0; SET GLOBAL long_query_time=10''; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, amount INT NOT NULL) ENGINE=InnoDB; INSERT INTO orders (customer_id, amount) SELECT seq % 1000, seq % 500 FROM seq_1_to_30000; CREATE TABLE logs (id INT AUTO_INCREMENT PRIMARY KEY, msg VARCHAR(255) NOT NULL) ENGINE=InnoDB; INSERT INTO logs (msg) SELECT REPEAT(\\"x\\", 200) FROM seq_1_to_20000; CREATE TABLE tags (id INT PRIMARY KEY, name VARCHAR(20)) ENGINE=InnoDB;''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(cat /tmp/requests.txt)\\" -gt 0 ] && [ \\"$(cat /tmp/reads.txt)\\" -ge 0 ] ) && ( [ \\"$(cat /tmp/requests.txt)\\" -gt \\"$(cat /tmp/reads.txt)\\" ] ) && ( [ \\"$(cat /tmp/requests.txt)\\" -ge 30000 ] && [ \\"$(cat /tmp/requests.txt)\\" -le \\"$(mariadb -N -e \\"SHOW GLOBAL STATUS LIKE ''Innodb_buffer_pool_read_requests''\\" | cut -f2)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "두 값이 숫자다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/requests.txt)\\" -gt 0 ] && [ \\"$(cat /tmp/reads.txt)\\" -ge 0 ]"]}, {"label": "요청이 디스크 읽기보다 많다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/requests.txt)\\" -gt \\"$(cat /tmp/reads.txt)\\" ]"]}, {"label": "요청 수가 실제 카운터를 넘지 않고 충분히 크다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/requests.txt)\\" -ge 30000 ] && [ \\"$(cat /tmp/requests.txt)\\" -le \\"$(mariadb -N -e \\"SHOW GLOBAL STATUS LIKE ''Innodb_buffer_pool_read_requests''\\" | cut -f2)\\" ]"]}]', '[{"title": "SHOW STATUS", "url": "https://mariadb.com/kb/en/show-status/"}, {"title": "서버 상태 변수", "url": "https://mariadb.com/kb/en/server-status-variables/"}]'),
  (559, 7, 'Handler 로 전체 훑기와 인덱스 사용 구분', '`Handler_read_rnd_next` 는 테이블을 **처음부터 끝까지 행 단위로 훑을 때** 늘어나는 세션 카운터입니다. `shop.orders`(3만 건)에서 `customer_id = 7` 인 주문 수를 세는 쿼리를 두 번 비교하세요.

1. 인덱스가 **없는** 지금: `FLUSH STATUS; SELECT COUNT(*) FROM orders WHERE customer_id = 7; SHOW SESSION STATUS LIKE ''Handler_read_rnd_next'';` 의 값을 `/tmp/before.txt` 에 저장
2. `customer_id` 에 인덱스를 만든 뒤 **같은 방법으로** 다시 재서 `/tmp/after.txt` 에 저장

(`FLUSH STATUS` 와 쿼리와 `SHOW` 는 **같은 접속**(한 번의 `mariadb -e`) 안에서 실행해야 합니다.)', '`mariadb -N shop -e "FLUSH STATUS; SELECT ...; SHOW SESSION STATUS LIKE ''...''"` 의 출력에는 쿼리 결과도 섞입니다. `tail -1 | cut -f2` 로 마지막 줄의 값만 뽑으세요.', 'mariadb -N shop -e "FLUSH STATUS; SELECT COUNT(*) FROM orders WHERE customer_id = 7; SHOW SESSION STATUS LIKE ''Handler_read_rnd_next''" | tail -1 | cut -f2 > /tmp/before.txt
mariadb shop -e ''CREATE INDEX idx_orders_customer ON orders (customer_id)''
mariadb -N shop -e "FLUSH STATUS; SELECT COUNT(*) FROM orders WHERE customer_id = 7; SHOW SESSION STATUS LIKE ''Handler_read_rnd_next''" | tail -1 | cut -f2 > /tmp/after.txt
cat /tmp/before.txt /tmp/after.txt

# before 는 3만 건을 모두 훑어 약 30000, after 는 인덱스만 보아 0 에 가깝다. EXPLAIN 없이도 전체 훑기를 숫자로 확인할 수 있다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; for id in $(mariadb -N -e \\"SELECT id FROM information_schema.processlist WHERE id<>CONNECTION_ID()\\"); do mariadb -e \\"KILL $id\\" >/dev/null 2>&1; done; mariadb -e ''SET GLOBAL slow_query_log=0; SET GLOBAL long_query_time=10''; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, amount INT NOT NULL) ENGINE=InnoDB; INSERT INTO orders (customer_id, amount) SELECT seq % 1000, seq % 500 FROM seq_1_to_30000; CREATE TABLE logs (id INT AUTO_INCREMENT PRIMARY KEY, msg VARCHAR(255) NOT NULL) ENGINE=InnoDB; INSERT INTO logs (msg) SELECT REPEAT(\\"x\\", 200) FROM seq_1_to_20000; CREATE TABLE tags (id INT PRIMARY KEY, name VARCHAR(20)) ENGINE=InnoDB;''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(cat /tmp/before.txt)\\" -ge 30000 ] ) && ( [ \\"$(cat /tmp/after.txt)\\" -lt 1000 ] ) && ( [ \\"$(mariadb -N -e \\"SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=''shop'' AND table_name=''orders'' AND column_name=''customer_id''\\")\\" -ge 1 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "인덱스 전에는 전체를 훑었다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/before.txt)\\" -ge 30000 ]"]}, {"label": "인덱스 뒤에는 거의 훑지 않았다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/after.txt)\\" -lt 1000 ]"]}, {"label": "customer_id 인덱스가 있다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N -e \\"SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=''shop'' AND table_name=''orders'' AND column_name=''customer_id''\\")\\" -ge 1 ]"]}]', '[{"title": "SHOW STATUS", "url": "https://mariadb.com/kb/en/show-status/"}, {"title": "서버 상태 변수", "url": "https://mariadb.com/kb/en/server-status-variables/"}]'),
  (559, 8, '가장 큰 테이블 찾기', '`shop` 데이터베이스에 테이블이 셋(`orders`, `logs`, `tags`) 있습니다. `information_schema.tables` 의 `data_length`(데이터)와 `index_length`(인덱스) 를 더한 크기가 **가장 큰 테이블의 이름**을 `/tmp/biggest.txt` 에 저장하세요. (이름만)', '`SELECT table_name, data_length + index_length FROM information_schema.tables WHERE table_schema=''shop''` 에 `ORDER BY ... DESC LIMIT 1` 을 붙입니다.', 'mariadb -N -e "SELECT table_name FROM information_schema.tables WHERE table_schema=''shop'' ORDER BY data_length + index_length DESC LIMIT 1" > /tmp/biggest.txt
cat /tmp/biggest.txt

# 파일 시스템(du)을 뒤지지 않아도 SQL 로 테이블별 용량을 볼 수 있다. 용량 관리의 첫 단계', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; for id in $(mariadb -N -e \\"SELECT id FROM information_schema.processlist WHERE id<>CONNECTION_ID()\\"); do mariadb -e \\"KILL $id\\" >/dev/null 2>&1; done; mariadb -e ''SET GLOBAL slow_query_log=0; SET GLOBAL long_query_time=10''; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, amount INT NOT NULL) ENGINE=InnoDB; INSERT INTO orders (customer_id, amount) SELECT seq % 1000, seq % 500 FROM seq_1_to_30000; CREATE TABLE logs (id INT AUTO_INCREMENT PRIMARY KEY, msg VARCHAR(255) NOT NULL) ENGINE=InnoDB; INSERT INTO logs (msg) SELECT REPEAT(\\"x\\", 200) FROM seq_1_to_20000; CREATE TABLE tags (id INT PRIMARY KEY, name VARCHAR(20)) ENGINE=InnoDB;''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(cat /tmp/biggest.txt)\\" = logs ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "가장 큰 테이블이 logs 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/biggest.txt)\\" = logs ]"]}]', '[{"title": "SHOW STATUS", "url": "https://mariadb.com/kb/en/show-status/"}, {"title": "서버 상태 변수", "url": "https://mariadb.com/kb/en/server-status-variables/"}]'),
  (559, 9, 'performance_schema 는 어떻게 켜나', 'MariaDB 의 `performance_schema` 는 쿼리·락 대기 등을 자세히 모으는 진단 기능입니다. MariaDB 에서 이 기능의 기본 상태와 켜는 방법으로 맞는 것은?', 'MariaDB 와 MySQL 의 기본값이 다릅니다.', NULL, NULL, '[]', 'choice', '["기본은 켜져 있고, SET GLOBAL performance_schema=OFF 로 끌 수 있다", "기본은 꺼져 있고, SET GLOBAL performance_schema=ON 으로 바로 켠다", "별도 기능이라 MariaDB 에는 존재하지 않는다", "기본은 꺼져 있고, 설정 파일에 performance_schema=ON 을 적고 서버를 재시작해야 켜진다"]', 3, 'MariaDB 의 performance_schema 는 기본 OFF 이고 읽기 전용 시작 옵션이라 설정 파일에 적고 재시작해야 켤 수 있습니다(MySQL 은 기본 ON). 켜 두면 메모리 오버헤드가 있어 필요할 때만 씁니다. 켜기 전에는 STATUS 지표, PROCESSLIST, 느린 쿼리 로그, information_schema 로 대부분 진단합니다.', NULL, NULL, NULL, NULL),
  (559, 10, '버퍼 풀 적중률 공식', '버퍼 풀 적중률(읽기 요청 중 메모리에서 처리된 비율)의 공식에서 빈칸에 들어갈 상태 변수 이름의 끝부분을 채우세요.', '분자는 "메모리에 없어서 디스크까지 간 횟수"입니다.', NULL, NULL, '[]', 'fill', '["reads", "read_requests", "pages_data", "wait_free"]', NULL, '`Innodb_buffer_pool_reads` 는 버퍼 풀에서 못 찾아 디스크에서 읽은 횟수, `read_requests` 는 전체 읽기 요청입니다. 디스크에 간 비율을 1 에서 빼면 적중률입니다. `pages_data` 는 데이터가 든 페이지 수, `wait_free` 는 빈 페이지를 기다린 횟수입니다.', '[0]', '적중률 = 1 − Innodb_buffer_pool_{0} / Innodb_buffer_pool_read_requests', NULL, NULL),
  (559, 11, '서버가 느리다: 지표로 좁혀 가는 순서', '서비스가 느려졌습니다. 큰 그림에서 시작해 원인 쿼리로 좁혀 가는 순서로 놓으세요. 연결이 한도에 가까운지를 먼저 봅니다.', '넓은 지표에서 점점 구체적인 대상으로 좁혀 가세요.', NULL, NULL, '[]', 'order', '["EXPLAIN 으로 그 쿼리가 인덱스를 못 타는지 확인", "Threads_connected 로 연결 수가 한도에 가까운지 확인", "PROCESSLIST 로 오래 실행 중인 쿼리를 확인", "Threads_running 이 평소보다 높은지 확인"]', NULL, '연결 수(Threads_connected)로 한도 근처인지 보고, 실행 중 스레드(Threads_running)가 평소보다 높은지 확인해 서버가 일에 쫓기는지 판단합니다. 그다음 PROCESSLIST 에서 오래 걸리는 쿼리를 찾고, EXPLAIN 으로 원인을 분석합니다.', '[1, 3, 2, 0]', NULL, NULL, NULL);
